import assert from 'node:assert/strict';
import {createBudgetedCaller} from './rerank-fast-development.mjs';
import {rerankFastCase} from './rerank-fast-development-ranking.mjs';
let calls=0,saves=0;
const response=()=>Response.json({id:'synthetic-response',meta:{billed_units:{search_units:1}},results:[]});
const caller=createBudgetedCaller({apiKey:'synthetic',save:()=>{saves++},globalUsage:async()=>192348,fetchImpl:async()=>{assert.ok(saves>calls);calls++;return response();}});
for(let i=0;i<25;i++)await caller.call('rerank',{model:'rerank-v4.0-fast'},2000);
assert.deepEqual(caller.totals(),{consumed:50000,reserved:0});
await assert.rejects(()=>caller.call('rerank',{model:'rerank-v4.0-fast'},2000),/DEVELOPMENT_BUDGET_EXCEEDED/);assert.equal(calls,25);
const unknown=createBudgetedCaller({apiKey:'synthetic',save:()=>{},globalUsage:async()=>0,fetchImpl:async()=>{throw new Error('synthetic-network');}});
await assert.rejects(()=>unknown.call('rerank',{model:'rerank-v4.0-fast'},2000));
assert.deepEqual(unknown.totals(),{consumed:0,reserved:2000});
await assert.rejects(()=>unknown.call('rerank',{model:'rerank-v4.0-fast'},2000),/PREVIOUS_PROVIDER_RESULT_UNKNOWN/);
const global=createBudgetedCaller({apiKey:'synthetic',save:()=>{throw new Error('unexpected')},globalUsage:async()=>499000,fetchImpl:async()=>{throw new Error('unexpected')}});
await assert.rejects(()=>global.call('rerank',{},2000),/GLOBAL_BUDGET_EXCEEDED/);
const unbilled=createBudgetedCaller({apiKey:'synthetic',save:()=>{},globalUsage:async()=>0,fetchImpl:async()=>new Response('',{status:429})});
await assert.rejects(()=>unbilled.call('rerank',{},2000),/PROVIDER_REJECTED/);assert.deepEqual(unbilled.totals(),{consumed:0,reserved:0});
const provenance=new Map(['a','b','c'].map((s,i)=>[s,{unit:s,fingerprint:i<2?'same':'other',authority_level:'A',effective_from:'2026-01-01'}]));
const result=rerankFastCase({provenance,claimResults:[{claim:{key:'x'},rows:['a','b','c'].map((s,i)=>({source_snapshot_id:s,chunk_id:s,fast_score:1-i*.1}))}]});
assert.equal(result.collapsed,1);assert.equal(result.top.length,2);assert.equal(result.top[0].unit,'a');
console.log('통과: 25단위 상한·실제 정산·미확정 보존·전송 전 원장·일일 잔여·429·출처 중복');
